            const text = message.content;
            if (!text.trim()) continue;
            if (waveShieldIsProtected(text)) continue;
            if (waveShieldLooksShielded(text)) {
                if (message.role === 'system') firstSystem = true;
                if (message.role === 'user') firstUser = true;
                if (message.role === 'assistant') firstAssistant = true;
                continue;
            }
            const descriptor = Object.getOwnPropertyDescriptor(message, 'content');
            if (descriptor && descriptor.writable === false) continue;
            const hasAdvice = text.toLowerCase().includes('<advice') || text.includes('按照advice继续');
            let prefix = '';
            let suffix = '';
            if (message.role === 'system' && !firstSystem) {
                firstSystem = true;
                prefix = waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (message.role === 'user' && !firstUser) {
                firstUser = true;
                prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (message.role === 'assistant' && !firstAssistant) {
                firstAssistant = true;
                prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (cfg.mode === 'deep') {
                if (index === lastEligible || index === secondLast || index === thirdLast) {
                    prefix = waveShieldCommentBlock(4, 10, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL;
                    suffix = WAVE_SHIELD_NL + waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true);
                } else if (text.length >= 45 && !hasAdvice) {
                    prefix = waveShieldCommentBlock(3, 9, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                }
            }
            const updated = waveShieldInject(text, prefix, suffix, cfg, !hasAdvice);
            if (updated !== text) {
                message.content = updated;
                injected += 1;
            }
        } else if (Array.isArray(message.content)) {
            let touched = false;
            for (let partIndex = 0; partIndex < message.content.length; partIndex++) {
                const part = message.content[partIndex];
                if (!part || typeof part !== 'object' || part.type !== 'text' || typeof part.text !== 'string') continue;
                if (!part.text.trim() || waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
                const descriptor = Object.getOwnPropertyDescriptor(part, 'text');
                if (descriptor && descriptor.writable === false) continue;
                const isFirstSystemPart = message.role === 'system' && !firstSystem && partIndex === 0;
                if (isFirstSystemPart) firstSystem = true;
                const prefix = isFirstSystemPart
                    ? waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL
                    : '';
                const nextText = waveShieldInject(part.text, prefix, '', cfg, true);
                if (nextText !== part.text) {
                    part.text = nextText;
                    touched = true;
                }
            }
            if (touched) injected += 1;
        }
    }
    return injected;
}

function waveShieldGoogleNative(data) {
    if (!data || typeof data !== 'object') return 0;
    const cfg = waveShieldReadConfig();
    if (!cfg.enabled || cfg.mode === 'off') return 0;
    let injected = 0;
    const system = data.systemInstruction || data.system_instruction;
    if (system && Array.isArray(system.parts)) {
        for (let i = 0; i < system.parts.length; i++) {
            const part = system.parts[i];
            if (!part || typeof part.text !== 'string' || !part.text.trim()) continue;
            if (waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
            const prefix = i === 0
                ? waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL
                : (cfg.mode === 'deep' ? waveShieldCommentBlock(4, 10, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL : '');
            const updated = waveShieldInject(part.text, prefix, '', cfg, true);
            if (updated !== part.text) {
                part.text = updated;
                injected += 1;
            }
        }
    }
    if (Array.isArray(data.contents)) {
        const length = data.contents.length;
        for (let i = 0; i < length; i++) {
            const turn = data.contents[i];
            if (!turn || !Array.isArray(turn.parts)) continue;
            for (let p = 0; p < turn.parts.length; p++) {
                const part = turn.parts[p];
                if (!part || typeof part.text !== 'string' || !part.text.trim()) continue;
                if (waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
                const hasAdvice = part.text.toLowerCase().includes('<advice') || part.text.includes('按照advice继续');
                let prefix = '';
                let suffix = '';
                if (i <= 1 && p === 0) {
                    prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                } else if (cfg.mode === 'deep') {
                    if (i >= length - 2 && p === turn.parts.length - 1) {
                        prefix = waveShieldCommentBlock(4, 9, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL;
                        suffix = WAVE_SHIELD_NL + waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true);
                    } else if (part.text.length >= 45 && !hasAdvice) {
                        prefix = waveShieldCommentBlock(4, 9, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                    }
                }
                const updated = waveShieldInject(part.text, prefix, suffix, cfg, !hasAdvice);
                if (updated !== part.text) {
                    part.text = updated;
                    injected += 1;
                }
            }
        }
    }
    return injected;
}

/* 浪潮搬运脚本把资料打包进 tools[].function.description，这里单独补一层 */
function waveShieldTools(tools) {
    if (!Array.isArray(tools) || !tools.length) return 0;
