/*
 * 我即浪潮 · 正文交付通道 v1（只管输出，不碰资料打包）
 * 做法：不重排消息、不改搬运的边界与工具描述，只把这一轮要交的正文
 * 从普通消息内容改走工具参数，回来时再逐块还原成普通正文。
 * 传输中途断开时，已经到达的字先吐出来，不整条丢。
 * 只在检测到搬运脚本的 wave_context_reference 工具时接管，其余请求一律放行。
 */
(() => {
  'use strict';

  const SLOT = '__WAVE_DELIVERY_CHANNEL_V1__';
  const HOST_TOOL = 'wave_context_reference';
  const PARAM = 'manuscript';
  const NL = String.fromCharCode(10);
  const BS = String.fromCharCode(92);
  const QUOTE = String.fromCharCode(34);
  const TAB = String.fromCharCode(9);
  const CR = String.fromCharCode(13);
  const CONTROL = '【本轮交付方式】前面提到的“无需调用”只针对查资料；这一步是把正文交出来。请调用一次 wave_context_reference，把完整正文（含所有约定标签）写进 manuscript 参数，不要另写一遍。';
  const state = { installed: false, shaped: 0, empty: 0 };

  const hostWin = (() => {
    try { if (window.top && window.top !== window) return window.top; } catch (e) {}
    try { if (window.parent && window.parent !== window) return window.parent; } catch (e) {}
    return window;
  })();

  function toolName(tool) {
    try { return (tool && tool.function && tool.function.name) || ''; } catch (e) { return ''; }
  }

  function isSpace(ch) {
    return ch === ' ' || ch === NL || ch === TAB || ch === CR;
  }

  function isGenerationUrl(url) {
    if (typeof url !== 'string') return false;
    return url.indexOf('/api/backends/') >= 0 && url.indexOf('/generate') >= 0;
  }

  function valueStart(raw, key) {
    const needle = QUOTE + key + QUOTE;
    const at = raw.indexOf(needle);
    if (at < 0) return -1;
    let i = at + needle.length;
    while (i < raw.length && isSpace(raw[i])) i += 1;
    if (raw[i] !== ':') return -1;
    i += 1;
    while (i < raw.length && isSpace(raw[i])) i += 1;
    if (raw[i] !== QUOTE) return -1;
    return i + 1;
  }

  function decodeRun(raw, start) {
    let out = '';
    let i = start;
    while (i < raw.length) {
      const ch = raw[i];
      if (ch === BS) {
        const next = raw[i + 1];
        if (next === undefined) break;
        if (next === 'n') { out += NL; i += 2; continue; }
        if (next === 't') { out += TAB; i += 2; continue; }
        if (next === 'r') { out += CR; i += 2; continue; }
        if (next === 'u') {
          const hex = raw.slice(i + 2, i + 6);
          if (hex.length < 4) break;
          const code = parseInt(hex, 16);
          if (isNaN(code)) break;
          out += String.fromCharCode(code);
          i += 6;
          continue;
