    let carrier = null;
    for (let i = 0; i < tools.length; i += 1) {
      if (toolName(tools[i]) === HOST_TOOL) { carrier = tools[i]; continue; }
      return false;
    }
    if (!carrier || !carrier.function) return false;
    carrier.function.description = '本轮交付方式：调用一次本工具，把完整正文写进 manuscript 参数。' + NL + NL + (carrier.function.description || '');
    carrier.function.parameters = {
      type: 'object',
      properties: { [PARAM]: { type: 'string', description: '本轮要交的完整正文，含全部标签。' } },
      required: [PARAM]
    };
    body.tool_choice = 'required';
    const last = body.messages[body.messages.length - 1];
    if (last && last.role === 'user' && typeof last.content === 'string') {
      last.content = last.content + NL + NL + CONTROL;
    } else {
      body.messages.push({ role: 'system', content: CONTROL });
    }
    state.shaped += 1;
    return true;
  }

  function streamOf(upstream) {
    const reader = upstream.getReader();
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    const meta = { id: 'chatcmpl-wave', model: 'unknown', created: Math.floor(Date.now() / 1000) };
    let buffer = '';
    let rawArgs = '';
    let sent = 0;
    let emitted = 0;
    let announced = false;

    function emit(text) {
      if (!text) return '';
      emitted += text.length;
      const delta = announced ? { content: text } : { role: 'assistant', content: text };
      announced = true;
      return 'data: ' + JSON.stringify({
        id: meta.id,
        object: 'chat.completion.chunk',
        created: meta.created,
        model: meta.model,
        choices: [{ index: 0, delta: delta, finish_reason: null }]
      }) + NL + NL;
    }

    function finish() {
      return 'data: ' + JSON.stringify({
        id: meta.id,
        object: 'chat.completion.chunk',
        created: meta.created,
        model: meta.model,
        choices: [{ index: 0, delta: {}, finish_reason: 'stop' }]
      }) + NL + NL + 'data: [DONE]' + NL + NL;
    }

    function feed(fragment) {
      rawArgs += fragment;
      const start = valueStart(rawArgs, PARAM);
      if (start < 0) return '';
      const value = decodeRun(rawArgs, start);
      if (value.length <= sent) return '';
      const delta = value.slice(sent);
      sent = value.length;
      return emit(delta);
    }

    function handle(raw) {
      const lines = raw.split(NL);
      let line = '';
      for (let i = 0; i < lines.length; i += 1) {
        if (lines[i].indexOf('data:') === 0) { line = lines[i]; break; }
      }
      if (!line) return '';
      const payload = line.slice(5).trim();
      if (payload === '[DONE]') return '';
      let obj;
      try { obj = JSON.parse(payload); } catch (e) { return ''; }
      if (!obj || typeof obj !== 'object') return '';
      if (typeof obj.id === 'string') meta.id = obj.id;
      if (typeof obj.model === 'string') meta.model = obj.model;
      if (typeof obj.created === 'number') meta.created = obj.created;
      let out = '';
      const choices = obj.choices;
      if (Array.isArray(choices)) {
        for (let i = 0; i < choices.length; i += 1) {
          const delta = choices[i] && choices[i].delta ? choices[i].delta : {};
          if (typeof delta.content === 'string' && delta.content) out += emit(delta.content);
          if (Array.isArray(delta.tool_calls)) {
            for (let k = 0; k < delta.tool_calls.length; k += 1) {
              const fn = delta.tool_calls[k] && delta.tool_calls[k].function;
              if (fn && typeof fn.arguments === 'string') out += feed(fn.arguments);
            }
          }
        }
      }
      const candidates = obj.candidates;
      if (Array.isArray(candidates) && candidates[0]) {
        const parts = candidates[0].content && candidates[0].content.parts;
        if (Array.isArray(parts)) {
          for (let i = 0; i < parts.length; i += 1) {
            const part = parts[i];
            if (!part) continue;
            if (typeof part.text === 'string' && part.text) out += emit(part.text);
            if (part.functionCall) {
              const args = part.functionCall.args;
              if (typeof args === 'string') out += feed(args);
              else if (args && typeof args === 'object' && typeof args[PARAM] === 'string') {
                if (args[PARAM].length > sent) { out += emit(args[PARAM].slice(sent)); sent = args[PARAM].length; }
              }
            }
          }
        }
      }
      return out;
    }

    return new ReadableStream({
      async pull(controller) {
        let step;
        try { step = await reader.read(); } catch (e) {
          controller.enqueue(encoder.encode(finish()));
          controller.close();
          return;
        }
        if (step.done) {
          if (emitted === 0) {
            state.empty += 1;
            controller.enqueue(encoder.encode(emit('【交付通道】本轮没有收到正文，模型可能没有按约定调用交付工具。')));
          }
          controller.enqueue(encoder.encode(finish()));
          controller.close();
          return;
        }
        buffer += decoder.decode(step.value, { stream: true });
        let cut = buffer.indexOf(NL + NL);
        while (cut >= 0) {
          const raw = buffer.slice(0, cut);
          buffer = buffer.slice(cut + 2);
          const text = handle(raw);
          if (text) controller.enqueue(encoder.encode(text));
          cut = buffer.indexOf(NL + NL);
        }
      },
      cancel(reason) {
        try { return reader.cancel(reason); } catch (e) { return undefined; }
      }
    });
  }

  function rebuild(text, upstream, keepType) {
    const headers = new Headers();
    let type = 'application/json';
    try { if (keepType) type = upstream.headers.get('content-type') || type; } catch (e) {}
    headers.set('content-type', type);
    return new Response(text, { status: upstream.status, statusText: upstream.statusText, headers: headers });
  }

  async function rewriteJson(response) {
    let text;
    try { text = await response.text(); } catch (e) { return response; }
    let obj;
    try { obj = JSON.parse(text); } catch (e) { return rebuild(text, response, true); }
    let got = '';
    try {
      const choices = obj.choices;
      if (Array.isArray(choices) && choices[0] && choices[0].message) {
        const message = choices[0].message;
        const calls = message.tool_calls;
        if (Array.isArray(calls)) {
          for (let i = 0; i < calls.length; i += 1) {
            const fn = calls[i] && calls[i].function;
            if (!fn) continue;
            const args = typeof fn.arguments === 'string' ? JSON.parse(fn.arguments) : fn.arguments;
            if (args && typeof args[PARAM] === 'string' && args[PARAM].length > got.length) got = args[PARAM];
