      const candidates = obj.candidates;
      if (!got && Array.isArray(candidates) && candidates[0]) {
        const parts = candidates[0].content && candidates[0].content.parts;
        if (Array.isArray(parts)) {
          for (let i = 0; i < parts.length; i += 1) {
            const fc = parts[i] && parts[i].functionCall;
            if (!fc) continue;
            const args = typeof fc.args === 'string' ? JSON.parse(fc.args) : fc.args;
            if (args && typeof args[PARAM] === 'string' && args[PARAM].length > got.length) got = args[PARAM];
          }
