  function dispose() {
    try {
      if (hostWin.fetch && hostWin.fetch.__WAVE_DELIVERY__) hostWin.fetch = hostWin.fetch.__WAVE_DELIVERY__.original;
    } catch (e) {}
    state.installed = false;
    try { delete hostWin[SLOT]; } catch (e) {}
  }

  function install() {
