      const response = await original.call(this || target, input, next);
      try {
        const type = response && response.headers ? response.headers.get('content-type') || '' : '';
        if (response && response.body && type.indexOf('event-stream') >= 0) {
          const headers = new Headers();
          headers.set('content-type', 'text/event-stream');
          return new Response(streamOf(response.body), { status: response.status, statusText: response.statusText, headers: headers });
        }
        return await rewriteJson(response);
      } catch (e) {
        return response;
      }
    };
    wrapped.__WAVE_DELIVERY__ = { original: original };
    target.fetch = wrapped;
    state.installed = true;
    try { hostWin[SLOT] = { state: state, dispose: dispose }; } catch (e) {}
    try { console.info('[浪潮交付通道] 已接管输出：正文经工具参数交付并还原'); } catch (e) {}
  }

  install();
})();

/*
 * 我即浪潮 · 正文交付通道 v2（只管输出）
 * v1 边收边猜流格式，结果酒馆拿到的还是原始 tool_call，触发工具调用循环。
 * v2 改成：整段读完 -> 先看开头是不是 data: -> 按 SSE 或 JSON 解 -> 取 manuscript ->
 * 返回一份全新的响应。无论解析成功与否，都不会把 tool_call 原样交回酒馆。
 * 代价：没有逐字打字效果，整段生成完才显示。
 */
(() => {
  'use strict';

  const SLOT = '__WAVE_DELIVERY_CHANNEL_V2__';
  const HOST_TOOL = 'wave_context_reference';
  const PARAM = 'manuscript';
  const NL = String.fromCharCode(10);
  const CR = String.fromCharCode(13);
  const BS = String.fromCharCode(92);
  const QUOTE = String.fromCharCode(34);
  const TAB = String.fromCharCode(9);
  const CONTROL = '【本轮交付方式】前面提到的“无需调用”只针对查资料；这一步是把正文交出来。请调用一次 wave_context_reference，把完整正文（含所有约定标签）写进 manuscript 参数，不要另写一遍。参数值里的换行写成真正的换行，不要写成反斜杠加 n 的转义。';
  const NOTICE = '【交付通道】这一轮没有读回正文。请把“正文交付通道 v2”脚本关掉后重试。';

  const hostWin = (() => {
    try { if (window.top && window.top !== window) return window.top; } catch (e) {}
    try { if (window.parent && window.parent !== window) return window.parent; } catch (e) {}
    return window;
  })();

  function toolName(tool) {
    try { return (tool && tool.function && tool.function.name) || ''; } catch (e) { return ''; }
  }

  function isSpace(ch) {
    return ch === ' ' || ch === NL || ch === TAB || ch === CR;
  }

  function isGenerationUrl(url) {
    if (typeof url !== 'string') return false;
    return url.indexOf('/api/backends/') >= 0 && url.indexOf('/generate') >= 0;
  }

  function hasToolMessage(messages) {
    for (let i = 0; i < messages.length; i += 1) {
      if (messages[i] && messages[i].role === 'tool') return true;
    }
    return false;
  }

  function valueStart(raw, key) {
    const needle = QUOTE + key + QUOTE;
    const at = raw.indexOf(needle);
    if (at < 0) return -1;
    let i = at + needle.length;
    while (i < raw.length && isSpace(raw[i])) i += 1;
    if (raw[i] !== ':') return -1;
    i += 1;
    while (i < raw.length && isSpace(raw[i])) i += 1;
    if (raw[i] !== QUOTE) return -1;
    return i + 1;
  }

  function decodeRun(raw, start) {
    let out = '';
    let i = start;
    while (i < raw.length) {
      const ch = raw[i];
      if (ch === BS) {
        const next = raw[i + 1];
        if (next === undefined) break;
        if (next === 'n') { out += NL; i += 2; continue; }
        if (next === 't') { out += TAB; i += 2; continue; }
        if (next === 'r') { out += CR; i += 2; continue; }
        if (next === 'u') {
          const hex = raw.slice(i + 2, i + 6);
          if (hex.length < 4) break;
          const code = parseInt(hex, 16);
          if (isNaN(code)) break;
          out += String.fromCharCode(code);
          i += 6;
          continue;
        }
        out += next;
        i += 2;
        continue;
      }
      if (ch === QUOTE) break;
      out += ch;
      i += 1;
    }
    return out;
  }

  // 有些模型把换行写成字面的反斜杠加 n（甚至转义两层）；正文还原时统一折回真换行。
  function squashEscapes(text) {
    if (typeof text !== 'string' || !text) return text;
    const mark = BS + 'n';
    const marks = text.split(mark).length - 1;
    if (!marks) return text;
    const realLines = text.split(NL).length - 1;
    if (marks < 2 || marks < realLines) return text;
    let out = text.split(BS + BS).join(BS);
    out = out.split(BS + 'r' + BS + 'n').join(NL);
    out = out.split(mark).join(NL);
    return out.split(BS + 'r').join(NL);
  }

  function shape(body) {
    if (!body || typeof body !== 'object') return false;
    if (!Array.isArray(body.messages) || !body.messages.length) return false;
    if (hasToolMessage(body.messages)) return false;
    const tools = Array.isArray(body.tools) ? body.tools : [];
    let carrier = null;
    for (let i = 0; i < tools.length; i += 1) {
      if (toolName(tools[i]) === HOST_TOOL) { carrier = tools[i]; continue; }
      return false;
    }
    if (!carrier || !carrier.function) return false;
    carrier.function.description = '本轮交付方式：调用一次本工具，把完整正文写进 manuscript 参数。' + NL + NL + (carrier.function.description || '');
    carrier.function.parameters = {
      type: 'object',
      properties: { [PARAM]: { type: 'string', description: '本轮要交的完整正文，含全部标签。' } },
      required: [PARAM]
    };
    body.tool_choice = 'required';
    const last = body.messages[body.messages.length - 1];
    if (last && last.role === 'user' && typeof last.content === 'string') {
      last.content = last.content + NL + NL + CONTROL;
    } else {
      body.messages.push({ role: 'system', content: CONTROL });
    }
    return true;
  }

  function fromJson(text, meta) {
    const result = { content: '', sawTool: false, patched: null };
    let obj;
    try { obj = JSON.parse(text); } catch (e) { return result; }
    if (!obj || typeof obj !== 'object') return result;
    if (typeof obj.id === 'string') meta.id = obj.id;
    if (typeof obj.model === 'string') meta.model = obj.model;
    if (typeof obj.created === 'number') meta.created = obj.created;
    let argsText = '';
    const choices = obj.choices;
    if (Array.isArray(choices) && choices[0] && choices[0].message) {
      const message = choices[0].message;
      if (Array.isArray(message.tool_calls)) {
        result.sawTool = true;
        for (let i = 0; i < message.tool_calls.length; i += 1) {
          const fn = message.tool_calls[i] && message.tool_calls[i].function;
          if (fn && typeof fn.arguments === 'string') argsText += fn.arguments;
        }
      }
