    const candidates = obj.candidates;
    if (Array.isArray(candidates) && candidates[0]) {
      const parts = candidates[0].content && candidates[0].content.parts;
      if (Array.isArray(parts)) {
        for (let i = 0; i < parts.length; i += 1) {
          const part = parts[i];
