          result.sawTool = true;
          const args = part.functionCall.args;
          if (typeof args === 'string') argsText += args;
          else if (args && typeof args === 'object' && typeof args[PARAM] === 'string' && args[PARAM].length > result.content.length) result.content = args[PARAM];
