    const head = 'data: ' + JSON.stringify({
      id: meta.id,
      object: 'chat.completion.chunk',
      created: meta.created,
      model: meta.model,
      choices: [{ index: 0, delta: { role: 'assistant', content: content }, finish_reason: null }]
