      id: meta.id,
      object: 'chat.completion.chunk',
      created: meta.created,
      model: meta.model,
      choices: [{ index: 0, delta: {}, finish_reason: 'stop' }]
    }) + NL + NL + 'data: [DONE]' + NL + NL;
    return head + tail;
