  async function deliver(response, wantStream) {
    const meta = { id: 'chatcmpl-wave', model: 'unknown', created: Math.floor(Date.now() / 1000) };
    let text = '';
    try { text = await response.text(); } catch (e) { return response; }
    let head = text;
    while (head.length && isSpace(head[0])) head = head.slice(1);
