// Trusted message-iframe code. Model text is read as data, never inserted as HTML.
// API/source baseline: Tavern Helper 4.11.3, e71c990607f6c92127151b1f8dad6c79fa03966e.
function createWavePanelRuntime(config) {
  const tags = {plan:'wave_plan',mind:'wave_mind',options:'wave_options',summary:'wave_summary',review:'wave_review',comment:'wave_comment'};
  // 模型偶尔把换行写成字面的反斜杠加 n，这里先还原成真换行，再交给解析与渲染。
  const waveSquash = (value) => {
    let text = String(value ?? '');
    const B = String.fromCharCode(92);
    if (text.indexOf(B + 'n') === -1 && text.indexOf(B + 'r') === -1) return text;
    text = text.split(B + B).join(B);
    return text.split(B + 'r' + B + 'n').join('\n').split(B + 'n').join('\n').split(B + 'r').join('\n');
  };
  function extract(raw, kind) {
    if (typeof raw !== 'string' || !tags[kind]) return [];
    if (kind === 'plan') {
      const match = /<wave_plan>\s*([\s\S]*?)(?:<(\/)wave_plan>|(?=<(content)>)(?![\s\S]*<\/wave_plan>)|$)/i.exec(raw);
      return match ? [{text:waveSquash(match[1]), state:match[2] || match[3] ? '/' : ''}] : [];
    }
    const tag = tags[kind];
    return Array.from(raw.matchAll(new RegExp('<'+tag+'>[ \\t]*(?:\\r?\\n)?([\\s\\S]*?)<\\/'+tag+'>','gi')), match => ({text:waveSquash(match[1]),state:'/'}));
  }
  function inline(target, value, doc) {
    // Deliberately small Markdown subset: no HTML, links, images or commands.
    const tokens = /\*\*([^*\n]+)\*\*|`([^`\n]+)`|\*([^*\n]+)\*/g;
    let offset=0;
    for (const match of value.matchAll(tokens)) {
      target.append(doc.createTextNode(value.slice(offset,match.index)));
      const node=doc.createElement(match[1]!==undefined?'strong':match[2]!==undefined?'code':'em');
      node.textContent=match[1] ?? match[2] ?? match[3]; target.append(node);
      offset=match.index+match[0].length;
    }
    target.append(doc.createTextNode(value.slice(offset)));
  }
