    optionItems=actions.parse(text);
    if(!optionItems.length){renderText(target,text);const note=document.querySelector('[data-wave-action-feedback]');note.textContent='选项编号尚不完整；可先阅读原文，完整的 1—5 条选项才会启用点击。';note.setAttribute('data-error','');return;}
    target.replaceChildren();
    const list=document.createElement('ol');list.setAttribute('data-wave-choices','');
    for(const [index,item] of optionItems.entries()){
      const li=document.createElement('li'),button=document.createElement('button');
