  async function refresh() {
    if (disposed) return;
    const panel=document.querySelector('[data-wave-ui]'), copy=document.querySelector('[data-wave-copy]'), phase=document.querySelector('[data-wave-phase]');
    let busy=false;
    try {
      if (typeof getCurrentMessageId!=='function' || typeof getChatMessages!=='function') throw new Error('无法读取本楼消息：请确认正在使用酒馆助手的楼层前端，并启用了渲染器。兼容客户端还需提供本楼消息读取接口。');
      const id=getCurrentMessageId();
      const rows=await getChatMessages(id);
      const row=rows.find(item=>item.message_id===id);
      if (!row || typeof row.message!=='string') throw new Error('本楼消息暂未保存或尚未就绪；请等回复结束，再刷新本楼。');
      const blocks=extract(row.message,config.kind);
      if (!blocks.length) throw new Error('本楼缺少完整的对应条目，或其它正则改变了来源标签；请检查消息原文。');
      const block=blocks[occurrence(blocks.length)];
      if (!block) throw new Error('没有找到与这个面板对应的内容；请刷新本楼。');
      busy=config.kind==='plan' && block.state==='';
      panel.setAttribute('data-wave-state',block.state);
      if (phase) {phase.textContent=busy?'正在构思':'规划完成';phase.toggleAttribute('data-wave-busy',busy);phase.toggleAttribute('data-wave-done',!busy);}
